<main class="dashboard-container" aria-labelledby="patient-notifications-title"><div class="page-heading"><div><div class="page-eyebrow">Patient portal / updates</div><h1 id="patient-notifications-title" class="h3 mb-1">Notifications</h1><div class="text-muted">Clinic-scoped updates and reminders.</div></div><span class="badge badge-primary"><i class="bi bi-bell mr-1" aria-hidden="true"></i><?= (int) $unread ?> unread</span></div>
<div class="card"><div class="card-header d-flex flex-wrap align-items-center justify-content-between"><h2 class="h5 mb-2 mb-md-0">Notification inbox</h2><button class="btn btn-sm btn-light" type="button" data-toggle="modal" data-target="#patient-notification-filters"><i class="bi bi-funnel mr-1" aria-hidden="true"></i>Filters</button></div><div class="list-group list-group-flush"><?php if ($notifications === []): ?><div class="empty-state" role="status"><i class="bi bi-bell-slash d-block h3 mb-2" aria-hidden="true"></i><div>No notifications found</div><small>New clinic updates will appear here.</small></div><?php else: ?><?php foreach ($notifications as $notification): ?><article class="list-group-item d-flex flex-wrap align-items-start justify-content-between <?= $notification['status'] === 'unread' ? 'font-weight-bold' : '' ?>"><div class="pr-3"><div><?= esc($notification['title']) ?> <span class="badge <?= $notification['status'] === 'unread' ? 'badge-primary' : 'badge-light' ?>"><?= esc(ucfirst($notification['status'])) ?></span></div><p class="text-muted mb-1 small font-weight-normal"><?= nl2br(esc($notification['message'])) ?></p><small class="text-muted font-weight-normal"><?= esc($notification['created_at']) ?></small></div><?php if ($notification['status'] === 'unread'): ?><button type="button" class="btn btn-sm btn-outline-primary mark-notification-read" data-id="<?= (int) $notification['id'] ?>">Mark as read</button><?php endif; ?></article><?php endforeach; ?><?php endif; ?></div><?= view(PATIENT_VIEW . 'parts/notification_pagination', ['pagination' => $pagination ?? [], 'filters' => $filters ?? []]) ?></div></main>
<div class="modal fade" id="patient-notification-filters" tabindex="-1" role="dialog" aria-labelledby="patient-notification-filters-title" aria-hidden="true"><div class="modal-dialog" role="document"><div class="modal-content"><form method="get" action="<?= current_url() ?>"><div class="modal-header"><h2 class="modal-title h5" id="patient-notification-filters-title">Filter notifications</h2><button type="button" class="close" data-dismiss="modal" aria-label="Close"><span aria-hidden="true">&times;</span></button></div><div class="modal-body"><div class="form-group"><label for="patient-notification-search">Search</label><input class="form-control" id="patient-notification-search" name="search" value="<?= esc($filters['search'] ?? '') ?>" placeholder="Title or message"></div><div class="form-group"><label for="patient-notification-status">Status</label><select class="form-control btSelect" id="patient-notification-status" name="status"><option value="">All statuses</option><option value="unread" <?= ($filters['status'] ?? '') === 'unread' ? 'selected' : '' ?>>Unread</option><option value="read" <?= ($filters['status'] ?? '') === 'read' ? 'selected' : '' ?>>Read</option></select></div></div><div class="modal-footer"><a class="btn btn-light" href="<?= current_url() ?>">Clear</a><button class="btn btn-primary" type="submit">Apply filters</button></div></form></div></div></div>
<?= $this->section('scripts') ?><script>$(function(){$('.mark-notification-read').on('click',function(){const button=$(this);ajaxRequest({url:'<?= base_url('patient/notifications') ?>/'+button.data('id')+'/read',data:{},success:function(r){if(r.status){showSuccess(r.msg);reload_page(500);}else showError(r.msg);}});});});</script><?= $this->endSection() ?>
